mapper.sql:
SELECT
FROM exp_org_post_rel opr INNER JOIN exp_post p ON opr.post_id = p.post_id LEFT JOIN exp_role r ON p.default_role_id = r.role_id
AND opr.org_id = #{orgId}
AND opr.status = #{status}
ORDER BY opr.sort_no ASC, p.sort_no ASC

mapper.select:
SELECT
FROM exp_org_post_rel opr INNER JOIN exp_post p ON opr.post_id = p.post_id LEFT JOIN exp_role r ON p.default_role_id = r.role_id WHERE opr.org_id = #{orgId}
AND opr.status = #{status}
ORDER BY opr.sort_no ASC
